// Original topic-specific visuals and coached activities. The existing graded bank stays read-only.
let serial = 0;
const C = (scene, task, correct, wrong1, wrong2, hint) => {
  const options = [["c", ...correct], ["w1", ...wrong1], ["w2", ...wrong2]].map(([id, text, why]) => ({ id, text, why, correct: id === 'c' }));
  const n = serial++ % 3; return { kind: 'choice', scene, task, options: options.slice(n).concat(options.slice(0, n)), hint };
};
const O = (scene, task, items, why, hint) => ({ kind: 'order', scene, task, items, why, hint });
const V = (type, title, cards, caption) => ({ type, title, cards: cards.map(([title, text]) => ({ title, text })), caption: caption || 'Use the patient’s findings and the prescribed plan to choose the next action.' });
const S = (title, task, cue, rule, trap) => ({ title, task, cue, rule, trap });
const L = (visual, steps, strategy, terms, sources = []) => ({ visual, steps, strategy, terms, sources });
